import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week4/generated/day5-visual.config.ts", `// Week 4, Day 5 — visual regression, deliberately kept out of the default suite.
//
// Two reasons this needs its own config:
//
//  1. On the very first run there is no baseline, so the test FAILS by design and
//     writes one. A default suite that goes red on a clean checkout is useless.
//  2. Baselines are platform-specific — Playwright stamps the browser and OS into
//     the filename (e.g. "-chromium-win32"). A baseline captured on Windows will
//     not match on macOS, Linux or CI.
//
// So the demo file is named .visualdemo.ts (the root config only collects
// *.spec.ts) and lives here instead.
//
//   npx playwright test -c week4/generated/day5-visual.config.ts
//   npx playwright test -c week4/generated/day5-visual.config.ts --update-snapshots
import { defineConfig, devices } from "@playwright/test";

export default defineConfig({
  testDir: ".",
  testMatch: ["day5-visual.visualdemo.ts"],
  reporter: [["list"]],
  use: {
    ...devices["Desktop Chrome"],
    // Pin the viewport. A different window size means a different screenshot,
    // which means a false failure — the single most common visual-test mistake.
    viewport: { width: 1280, height: 720 },
  },
  expect: {
    toHaveScreenshot: {
      // Allow a tiny amount of noise (anti-aliasing, font rendering) without
      // allowing a real change through.
      maxDiffPixelRatio: 0.01,
      // Freeze CSS animations and stop the caret blinking.
      animations: "disabled",
      caret: "hide",
    },
  },
});
`);

await writeProjectFile("week4/generated/day5-visual.visualdemo.ts", `// Week 4, Day 5 — comparing what a page LOOKS like, not what it says.
//
// Uses the-internet.herokuapp.com because visual baselines need a page that
// renders identically every time. The course's banking app does not: two
// screenshots taken 1.5s apart differ (31,868 vs 38,418 bytes), so a baseline
// built from it would be flaky by construction.
//
//   npx playwright test -c week4/generated/day5-visual.config.ts
//   ... --update-snapshots     to re-baseline after an intended change
import { test, expect } from "@playwright/test";

const STATIC_PAGE = "https://the-internet.herokuapp.com/tables";

test.describe("Visual regression", () => {
  test("Step 1 — the whole page matches its baseline", async ({ page }) => {
    await page.goto(STATIC_PAGE);

    // First run: no baseline exists, so this FAILS and writes one.
    // Second run onwards: compares pixel by pixel against that file.
    await expect(page).toHaveScreenshot("tables-page.png", { fullPage: true });
  });

  test("Step 2 — a single element, not the whole page", async ({ page }) => {
    await page.goto(STATIC_PAGE);

    // Far more robust than a full page: the smaller the region, the fewer
    // unrelated changes can break it.
    await expect(page.locator("#table1")).toHaveScreenshot("table1-only.png");
  });

  test("Step 3 — masking the parts you do not want compared", async ({ page }) => {
    await page.goto(STATIC_PAGE);

    // mask paints a box over regions that legitimately change — timestamps,
    // adverts, session ids — so the rest can still be compared.
    await expect(page).toHaveScreenshot("tables-masked.png", {
      fullPage: true,
      mask: [page.locator("#table2")],
    });
  });

  test("Step 4 — a screenshot saved to disk is NOT a comparison", async ({ page }, testInfo) => {
    await page.goto(STATIC_PAGE);

    // page.screenshot() only writes a file. Nothing is compared, nothing can fail.
    // Useful as evidence; useless as a test. toHaveScreenshot() is the assertion.
    const shot = await page.screenshot({ fullPage: false });
    expect(shot.length).toBeGreaterThan(1000);

    // Attaching it puts the image in the HTML report, which is the honest use.
    await testInfo.attach("tables-page", { body: shot, contentType: "image/png" });
  });
});
`);

await runSpec("week4/generated/day5-visual.visualdemo.ts", { extraArgs: ["-c", "week4/generated/day5-visual.config.ts"] });

import { chromium } from "npm:playwright";

const browser = await chromium.launch();
const page = await browser.newPage();
await page.goto("https://the-internet.herokuapp.com/tables");

// page.screenshot() WRITES PIXELS. It compares nothing. It cannot fail.
const bytes = await page.screenshot();
console.log("screenshot bytes:", bytes.length);
console.log("did it compare anything? no");

const elementBytes = await page.locator("#table1").screenshot();
console.log("element screenshot bytes:", elementBytes.length);
console.log("full page is larger:", bytes.length, ">", elementBytes.length);

await browser.close();

