const check = `
const a = await page.screenshot();
await page.waitForTimeout(1500);
const b = await page.screenshot();
const same = a.length === b.length && a.every((v, i) => v === b[i]);
console.log("deterministic:", same);   // false -> do not baseline this page
`.trim();

console.log(check);
console.log();
console.log("If false, your options are:");
for (const opt of [
  "wait for a real condition instead of a timeout",
  "mask the region that changes",
  "screenshot one stable element, not the page",
  "do not visual-test this page",
]) console.log("  -", opt);

